static int _CeApiStriCmp(const char* a, const char* b) {
    if (!a || !b) return (a == b) ? 0 : (a ? 1 : -1);
    for (; *a && *b; ++a, ++b) {
        char ca = (*a >= 'A' && *a <= 'Z') ? (char)(*a + 32) : *a;
        char cb = (*b >= 'A' && *b <= 'Z') ? (char)(*b + 32) : *b;
        if (ca != cb) return (ca > cb) ? 1 : -1;
    }
    return (*a == 0 && *b == 0) ? 0 : (*a ? 1 : -1);
}

const CE_API_TYPE* CeApi_FindType(const char* name) {
    for (int i = 0; g_ceApiTypes[i].name; ++i) {
        if (_CeApiStriCmp(g_ceApiTypes[i].name, name) == 0)
            return &g_ceApiTypes[i];
    }
    return NULL;
}

const CE_API_TYPE* CeApi_FindModule(const char* name) {
    return CeApi_FindType(name);
}

const char* CeApi_FunctionReturnType(const char* fnName) {
    for (int i = 0; g_ceApiFnRet[i].fn; ++i) {
        if (_CeApiStriCmp(g_ceApiFnRet[i].fn, fnName) == 0)
            return g_ceApiFnRet[i].type;
    }
    return NULL;
}
